object NbFonts {
    /** System face for all translated text (only weights 400 and 700, see tokens.json). */
    val sans: FontFamily = FontFamily.Default

    /** Barlow Condensed: digits, S/B/O, OUT, VS, room codes and #tags only. Latin only, never for translated strings. */
    val num: FontFamily = FontFamily(
        Font(R.font.barlow_condensed_medium, FontWeight.Medium),
        Font(R.font.barlow_condensed_semibold, FontWeight.SemiBold),
        Font(R.font.barlow_condensed_bold, FontWeight.Bold),
    )
}

object NbType {
    private fun sans(size: Int, line: Int, weight: FontWeight) =
        TextStyle(fontFamily = NbFonts.sans, fontSize = size.sp, lineHeight = line.sp, fontWeight = weight)

    private fun num(size: Int, line: Int, weight: FontWeight, tracking: Double = 0.0) = TextStyle(
        fontFamily = NbFonts.num,
        fontSize = size.sp,
        lineHeight = line.sp,
        fontWeight = weight,
        letterSpacing = tracking.em,
        fontFeatureSettings = "tnum",
    )

    val display = sans(40, 48, FontWeight.Bold)
    val headline = sans(26, 34, FontWeight.Bold)
    val title = sans(20, 28, FontWeight.Bold)
    val subtitle = sans(16, 22, FontWeight.Bold)
    val body = sans(15, 22, FontWeight.Normal)
    val bodyStrong = sans(15, 22, FontWeight.Bold)
    val label = sans(16, 20, FontWeight.Bold)
    val labelSmall = sans(13, 18, FontWeight.Bold)
    val caption = sans(13, 18, FontWeight.Normal)
    val micro = sans(12, 16, FontWeight.Bold)

    val numHero = num(56, 60, FontWeight.SemiBold)
    val numScore = num(56, 60, FontWeight.Bold)
    val numSlot = num(40, 44, FontWeight.SemiBold)
    val numCode = num(36, 40, FontWeight.SemiBold)
    val numStat = num(32, 36, FontWeight.SemiBold)
    val numKey = num(30, 36, FontWeight.Medium)
    val numSlotSm = num(28, 32, FontWeight.SemiBold)
    val numTimer = num(24, 28, FontWeight.SemiBold)
    val numLog = num(22, 28, FontWeight.Medium, tracking = 0.14)
    val numHint = num(20, 24, FontWeight.SemiBold, tracking = 0.02)
    val numMemo = num(18, 22, FontWeight.SemiBold)
    val numLabel = num(14, 16, FontWeight.SemiBold, tracking = 0.06)
    val numTag = num(15, 20, FontWeight.Medium, tracking = 0.02)
}

